<script setup lang="ts">
import { v4 as newRequestKey } from "uuid";
import { ref, watch } from "vue";
import { item, type TrialAvailability, type Subscription } from "@papilio/api";
import { useI18n } from "vue-i18n";
import { useLocalizedFormats } from "../../composables/useLocalizedFormats";
const props=defineProps<{customerId:number;admin?:boolean;canClaim:boolean}>();
const { t } = useI18n();
const { date, number } = useLocalizedFormats();
const offer=ref<TrialAvailability|null>(null);const state=ref<"loading"|"ready"|"error">("loading");const error=ref("");const busy=ref(false);const key=ref(newRequestKey());const accepted=ref<Subscription|null>(null);let version=0;
const reasonKeys:Record<string,string>={plan_inactive:"planInactive",plan_group_disabled:"groupInactive",trial_source_missing:"sourceMissing",trial_disabled:"disabled",trial_capacity:"capacity",trial_claim_limit:"claimLimit",trial_paid_customer:"paidCustomer",trial_active_exists:"activeExists",trial_cooldown:"cooldown",customer_inactive:"customerInactive"};
async function load():Promise<void>{const token=++version;state.value="loading";error.value="";try{const result=await item<TrialAvailability>(props.admin?`/v1/admin/customers/${props.customerId}/trial-availability`:"/v1/customer/trials/availability");if(token!==version)return;offer.value=result;state.value="ready";}catch(cause){if(token!==version)return;state.value="error";error.value=cause instanceof Error?cause.message:t("trialOffer.operationFailed");}}
async function claim():Promise<void>{if(busy.value||!offer.value?.eligible||props.canClaim===false)return;busy.value=true;error.value="";const customer=props.customerId;try{const result=await item<Subscription>(props.admin?`/v1/admin/customers/${customer}/trial`:"/v1/customer/trials","POST",{request_key:key.value});if(customer!==props.customerId)return;accepted.value=result;key.value=newRequestKey();await load();}catch(cause){if(customer!==props.customerId)return;error.value=cause instanceof Error?cause.message:t("trialOffer.operationFailed");}finally{busy.value=false;}}
watch(()=>props.customerId,()=>{accepted.value=null;key.value=newRequestKey();void load();},{immediate:true});
</script>
<template><section class="card card-pad form-grid"><h2>{{ t("trialOffer.title") }}</h2><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="state==='loading'">{{ t("trialOffer.checking") }}</p><button type="button" class="btn secondary" :disabled="busy" @click="load">{{ t("trialOffer.refresh") }}</button><template v-if="state==='ready' && offer"><p>{{ t("trialOffer.duration") }}: {{ number(offer.policy.duration_days, 0) }} {{ t("trialOffer.days") }} · {{ t("trialOffer.quota") }}: {{ number(offer.policy.quota_bytes, 0) }} {{ t("trialOffer.bytes") }} · {{ t("trialOffer.claims") }}: {{ number(offer.claims, 0) }}</p><p v-if="offer.reason">{{ t(`trialOffer.reasons.${reasonKeys[offer.reason]??'unavailable'}`) }}</p><p v-if="offer.reason==='trial_cooldown' && offer.next_claim_at">{{ t("trialOffer.nextClaim") }}: {{ date(offer.next_claim_at) }}</p><p>{{ t("trialOffer.policyNote") }}</p><button v-if="canClaim!==false" type="button" class="btn" :disabled="busy||!offer.eligible" @click="claim">{{ t("trialOffer.claim") }}</button></template><div v-if="accepted" class="hint-box"><p>{{ t("trialOffer.created", { id: number(accepted.id, 0) }) }}</p><RouterLink class="btn secondary" :to="admin?{path:'/subscriptions',query:{customer_id:customerId,subscription_id:accepted.id}}:{path:'/account',query:{subscription_id:accepted.id}}">{{ t("trialOffer.view") }}</RouterLink></div></section></template>
